-- 2026-11-20 owner's go: 2 free events a day (6:30 PM + 9:30 PM NPT) for 22-24 Nov = Open #34-#39.
-- Free = 1 free card or 15 points, prize Rs 175 (50/30/20), squad, 12 slots, mobile. Safe to re-run (skips names already there).
begin;
update public.site_content sc
set content = jsonb_set(
      jsonb_set(sc.content, '{tournaments}',
        (sc.content->'tournaments') || coalesce((select jsonb_agg(e) from jsonb_array_elements($j$[{"map": "bermuda", "date": "Sun, Nov 22", "game": "Free Fire BR · Squad", "map2": "solara", "map3": "kalahari", "mode": "squad", "name": "JD Free Fire Open #34", "time": "6:30 PM NPT", "entry": "Free", "prize": "175", "slots": 12, "start": "2026-11-22T18:30:00+05:45", "format": "BR · Best of 3", "status": "upcoming", "platform": "Mobile only", "registered": 0, "early_access": "yes", "platform_mode": "mobile", "teams": []}, {"map": "bermuda", "date": "Sun, Nov 22", "game": "Free Fire BR · Squad", "map2": "nexterra", "map3": "solara", "mode": "squad", "name": "JD Free Fire Open #35", "time": "9:30 PM NPT", "entry": "Free", "prize": "175", "slots": 12, "start": "2026-11-22T21:30:00+05:45", "format": "BR · Best of 3", "status": "upcoming", "platform": "Mobile only", "registered": 0, "early_access": "yes", "platform_mode": "mobile", "teams": []}, {"map": "bermuda", "date": "Mon, Nov 23", "game": "Free Fire BR · Squad", "map2": "kalahari", "map3": "nexterra", "mode": "squad", "name": "JD Free Fire Open #36", "time": "6:30 PM NPT", "entry": "Free", "prize": "175", "slots": 12, "start": "2026-11-23T18:30:00+05:45", "format": "BR · Best of 3", "status": "upcoming", "platform": "Mobile only", "registered": 0, "early_access": "yes", "platform_mode": "mobile", "teams": []}, {"map": "bermuda", "date": "Mon, Nov 23", "game": "Free Fire BR · Squad", "map2": "solara", "map3": "kalahari", "mode": "squad", "name": "JD Free Fire Open #37", "time": "9:30 PM NPT", "entry": "Free", "prize": "175", "slots": 12, "start": "2026-11-23T21:30:00+05:45", "format": "BR · Best of 3", "status": "upcoming", "platform": "Mobile only", "registered": 0, "early_access": "yes", "platform_mode": "mobile", "teams": []}, {"map": "bermuda", "date": "Tue, Nov 24", "game": "Free Fire BR · Squad", "map2": "nexterra", "map3": "solara", "mode": "squad", "name": "JD Free Fire Open #38", "time": "6:30 PM NPT", "entry": "Free", "prize": "175", "slots": 12, "start": "2026-11-24T18:30:00+05:45", "format": "BR · Best of 3", "status": "upcoming", "platform": "Mobile only", "registered": 0, "early_access": "yes", "platform_mode": "mobile", "teams": []}, {"map": "bermuda", "date": "Tue, Nov 24", "game": "Free Fire BR · Squad", "map2": "kalahari", "map3": "nexterra", "mode": "squad", "name": "JD Free Fire Open #39", "time": "9:30 PM NPT", "entry": "Free", "prize": "175", "slots": 12, "start": "2026-11-24T21:30:00+05:45", "format": "BR · Best of 3", "status": "upcoming", "platform": "Mobile only", "registered": 0, "early_access": "yes", "platform_mode": "mobile", "teams": []}]$j$::jsonb) e
           where not exists (select 1 from jsonb_array_elements(sc.content->'tournaments') x where x->>'name' = e->>'name')), '[]'::jsonb)),
      '{_published_at}', to_jsonb(to_char(now() at time zone 'utc','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')))
where sc.key = 'tournaments';
insert into public.tournament_capacity (tournament_slug, slots, platform_mode, updated_at)
select n, 12, 'mobile', now() from unnest(array['JD Free Fire Open #34','JD Free Fire Open #35','JD Free Fire Open #36','JD Free Fire Open #37','JD Free Fire Open #38','JD Free Fire Open #39']) n
on conflict (tournament_slug) do nothing;
select e->>'name' name, e->>'date' date, e->>'time' time, e->>'map2' m2, e->>'map3' m3
from public.site_content sc, jsonb_array_elements(sc.content->'tournaments') e
where sc.key='tournaments' and e->>'name' ~ 'Open #(3[4-9])$';
select count(*) capacity_rows from public.tournament_capacity where tournament_slug ~ 'Open #(3[4-9])$';
commit;
